{"content":"import pandas as pd

df = pd.read_csv('outputs/t02_eurostat_raw.csv')
duplicates = df[df.duplicated(subset=['city_id', 'city_name', 'year', 'indicator_id'], keep=False)]
if not duplicates.empty:
    print(f"Found {len(duplicates)} duplicate records:")
    print(duplicates)
else:
    print("No duplicates found.")
